INSERT INTO cards(type,title,description,options,effects,budget_effect,stat_effects) SELECT 'crisis','Fabrika Atık Skandalı','Organize sanayideki bir fabrikanın geceleri dereye kimyasal atık boşalttığı ortaya çıktı. Mahalleli ölü balık fotoğraflarını paylaşıyor.','[{"label": "Fabrikayı mühürle", "icon": "🔒", "cost": -20000, "desc": "Üretim durur, sanayici zarar eder.", "effects": {"health": 6, "social": 2, "businessman_cash": -120000}}, {"label": "Ağır para cezası kes", "icon": "🧾", "cost": 40000, "desc": "Kasaya para girer, atık sorunu sürer.", "effects": {"health": 2}}, {"label": "Bağışı al, sessiz kal", "icon": "🤫", "cost": 90000, "desc": "Fabrika belediyeye ''bağış'' yapar.", "effects": {"health": -6, "suspicion": 15, "businessman_cash": -40000}}]'::jsonb,NULL,0,NULL WHERE NOT EXISTS (SELECT 1 FROM cards WHERE title='Fabrika Atık Skandalı');
